import{_ as e,c as a,o as t,aj as r}from"./chunks/framework.DNhrqZu5.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/other/index.md","filePath":"guide/other/index.md","lastUpdated":1777547972000}'),o={name:"guide/other/index.md"},h=r('<h3 id="_1、为什么有多个组件库" tabindex="-1">1、为什么有多个组件库？ <a class="header-anchor" href="#_1、为什么有多个组件库" aria-label="Permalink to &quot;1、为什么有多个组件库？&quot;">​</a></h3><p>本模版想做到的是尽可能的开箱即用，不用去看别的文档引入相关组件库，毕竟做减法比做加法要容易些，如你不需要某个组件库可以根据<a href="/vue-h5-template/guide/vue3/ui.html">这篇指引</a>去移除某个组件库</p><h3 id="_2、我可以用在个人或公司的项目吗" tabindex="-1">2、我可以用在个人或公司的项目吗？ <a class="header-anchor" href="#_2、我可以用在个人或公司的项目吗" aria-label="Permalink to &quot;2、我可以用在个人或公司的项目吗？&quot;">​</a></h3><p>模版基于 MIT License，你可以根据自己的需求用到不同的项目里，如果对你有帮助点个 star 支持一下呗 🌟</p><h3 id="_3、我是一个新手-有什么好的学习建议吗" tabindex="-1">3、我是一个新手，有什么好的学习建议吗？ <a class="header-anchor" href="#_3、我是一个新手-有什么好的学习建议吗" aria-label="Permalink to &quot;3、我是一个新手，有什么好的学习建议吗？&quot;">​</a></h3><p>过来人的经验就是熟读文档可以少走很多弯路，很多的人文档没读熟就开始动手，出了问题也不知道如何去解决，墙裂建议先把<a href="https://cn.vuejs.org/" target="_blank" rel="noreferrer">文档</a>熟读</p><h3 id="_4、为什么-vue3-版本使用-history-模式而不是-hash" tabindex="-1">4、为什么 vue3 版本使用 history 模式而不是 hash？ <a class="header-anchor" href="#_4、为什么-vue3-版本使用-history-模式而不是-hash" aria-label="Permalink to &quot;4、为什么 vue3 版本使用 history 模式而不是 hash？&quot;">​</a></h3><p>Vue 3 版本默认使用 <code>createWebHistory</code>（history 模式），URL 更简洁美观。如需 hash 模式，参考<a href="/vue-h5-template/guide/vue3/router.html">路由文档</a>切换</p><h3 id="_5、viewport-适配时-ui-库组件尺寸不对" tabindex="-1">5、viewport 适配时 UI 库组件尺寸不对？ <a class="header-anchor" href="#_5、viewport-适配时-ui-库组件尺寸不对" aria-label="Permalink to &quot;5、viewport 适配时 UI 库组件尺寸不对？&quot;">​</a></h3><p>项目已通过 <code>customFun</code> 自动处理 Vant / NutUI / Varlet 的 375 设计稿和业务代码 750 设计稿的差异，无需手动处理</p><h3 id="_6、如何部署到生产环境" tabindex="-1">6、如何部署到生产环境？ <a class="header-anchor" href="#_6、如何部署到生产环境" aria-label="Permalink to &quot;6、如何部署到生产环境？&quot;">​</a></h3><p>项目内置了 <code>Dockerfile</code> + <code>nginx.conf</code>，可直接使用 Docker 部署。如使用 history 模式，确保服务端已配置 fallback</p>',12),i=[h];function s(d,n,c,l,_,u){return t(),a("div",null,i)}const m=e(o,[["render",s]]);export{f as __pageData,m as default};
